package ph.categoryclash.game;

import android.app.*;import android.os.*;import android.content.*;import android.graphics.*;import android.graphics.drawable.*;import android.media.MediaPlayer;import android.view.*;import android.view.inputmethod.InputMethodManager;import android.widget.*;import java.util.*;

public class MainActivity extends Activity{
 static final int NAVY=Color.rgb(9,17,31),PANEL=Color.rgb(18,31,52),GOLD=Color.rgb(245,196,81),TEAL=Color.rgb(21,174,151),RED=Color.rgb(211,67,75),PURPLE=Color.rgb(151,70,193),MUTED=Color.rgb(91,108,133),PALE=Color.rgb(187,201,221);
 final Random rng=new Random();final List<GameData.Category> categories=new ArrayList<>();LinearLayout root,content;CountDownTimer countdown;SharedPreferences prefs;
 String p1="Dan",p2="Norlyn",difficulty="EASY",firstChoice="Random",roundStarter,activePlayer,lastAnsweringPlayer,currentCategory,screen="home";int targetScore=5,turnSeconds=5,p1Score,p2Score,round=1;long remainingMs=5000;boolean soundOn=true,leftIsP1=true,timerRunning=false,roundOver=false;
 @Override public void onCreate(Bundle b){super.onCreate(b);hideSystemUI();prefs=getSharedPreferences("category_clash",MODE_PRIVATE);soundOn=prefs.getBoolean("sound",true);categories.addAll(GameData.load(this));home();}
 void hideSystemUI(){getWindow().setStatusBarColor(Color.TRANSPARENT);getWindow().setNavigationBarColor(Color.TRANSPARENT);getWindow().getDecorView().setSystemUiVisibility(View.SYSTEM_UI_FLAG_IMMERSIVE_STICKY|View.SYSTEM_UI_FLAG_FULLSCREEN|View.SYSTEM_UI_FLAG_HIDE_NAVIGATION|View.SYSTEM_UI_FLAG_LAYOUT_FULLSCREEN|View.SYSTEM_UI_FLAG_LAYOUT_HIDE_NAVIGATION|View.SYSTEM_UI_FLAG_LAYOUT_STABLE);if(Build.VERSION.SDK_INT>=30){WindowInsetsController c=getWindow().getInsetsController();if(c!=null){c.hide(WindowInsets.Type.statusBars()|WindowInsets.Type.navigationBars());c.setSystemBarsBehavior(WindowInsetsController.BEHAVIOR_SHOW_TRANSIENT_BARS_BY_SWIPE);}}}
 int dp(int n){return(int)(n*getResources().getDisplayMetrics().density+.5f);}GradientDrawable bg(int c,int r){GradientDrawable g=new GradientDrawable();g.setColor(c);g.setCornerRadius(dp(r));return g;}TextView text(String s,int z,int c){TextView v=new TextView(this);v.setText(s);v.setTextSize(z);v.setTextColor(c);v.setGravity(Gravity.CENTER);v.setPadding(dp(10),dp(7),dp(10),dp(7));return v;}Button button(String s,int c){Button b=new Button(this);b.setText(s);b.setTextSize(16);b.setTextColor(Color.WHITE);b.setAllCaps(false);b.setTypeface(null,Typeface.BOLD);b.setMinHeight(0);b.setMinimumHeight(0);b.setPadding(dp(8),0,dp(8),0);b.setBackground(bg(c,15));return b;}
 long turnMs(){return turnSeconds*1000L;}void base(){cancelTimer();timerRunning=false;root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);root.setBackgroundColor(NAVY);root.setPadding(dp(18),dp(8),dp(18),dp(9));setContentView(root);content=new LinearLayout(this);content.setOrientation(LinearLayout.VERTICAL);content.setGravity(Gravity.CENTER_HORIZONTAL);root.addView(content,new LinearLayout.LayoutParams(-1,0,1));}void title(String s){TextView t=text(s,24,GOLD);t.setTypeface(null,Typeface.BOLD);t.setGravity(Gravity.START|Gravity.CENTER_VERTICAL);content.addView(t,new LinearLayout.LayoutParams(-1,dp(42)));}void section(String s){TextView t=text(s,13,GOLD);t.setTypeface(null,Typeface.BOLD);t.setGravity(Gravity.START|Gravity.CENTER_VERTICAL);t.setPadding(dp(10),dp(2),dp(10),dp(2));LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,dp(30));p.setMargins(0,dp(2),0,0);content.addView(t,p);}LinearLayout row(){LinearLayout r=new LinearLayout(this);r.setOrientation(LinearLayout.HORIZONTAL);content.addView(r,new LinearLayout.LayoutParams(-1,-2));return r;}void bottom(Button b,int h){LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,dp(h));p.setMargins(0,dp(4),0,0);root.addView(b,p);}LinearLayout.LayoutParams weighted(float w,int h,int m){LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(0,dp(h),w);p.setMargins(dp(m),dp(2),dp(m),dp(2));return p;}
 void home(){screen="home";base();LinearLayout top=row();TextView spacer=text("",1,Color.WHITE),gear=text("⚙",28,GOLD);gear.setOnClickListener(v->appSettings());top.addView(spacer,new LinearLayout.LayoutParams(0,dp(40),1));top.addView(gear,new LinearLayout.LayoutParams(dp(60),dp(40)));content.addView(new LogoView(this),new LinearLayout.LayoutParams(-1,0,1));TextView sub=text("MABILISANG LABANAN NG MGA SAGOT",13,PALE);sub.setLetterSpacing(.08f);content.addView(sub,new LinearLayout.LayoutParams(-1,dp(30)));content.addView(text(categories.size()+" categories • 2 players • 5 or 10 seconds",13,Color.WHITE),new LinearLayout.LayoutParams(-1,dp(28)));Button start=button("START",GOLD);start.setTextColor(NAVY);start.setOnClickListener(v->howTo());bottom(start,48);}
 void howTo(){screen="how";base();title("How to Play");TextView body=text("May lalabas na category. Salitan kayong magbanggit ng sagot na pasok dito. Kapag nakasagot, pindutin agad ang sariling malaking button para ipasa ang turn.\n\nPumili ng 5 o 10 seconds bawat turn. Kapag naubos ang oras, may 1 point ang kalaban. Bawal ulitin ang sagot. Gamitin ang CHALLENGE kapag mali, wala sa category, o naulit ang sagot.\n\nAng unang sasagot ay salitan bawat round. Ang unang makaabot sa winning score ang panalo.",15,Color.WHITE);body.setGravity(Gravity.START|Gravity.CENTER_VERTICAL);body.setLineSpacing(0,1.05f);body.setBackground(bg(PANEL,16));content.addView(body,new LinearLayout.LayoutParams(-1,0,1));Button go=button("GAME SETTINGS",GOLD);go.setTextColor(NAVY);go.setOnClickListener(v->settings());bottom(go,48);Button back=button("BACK",PANEL);back.setOnClickListener(v->home());bottom(back,43);}
 void appSettings(){screen="appSettings";base();title("Settings");section("Sound Effects");LinearLayout r=row();Button on=button("ON",soundOn?GOLD:PANEL),off=button("OFF",soundOn?PANEL:GOLD);on.setTextColor(soundOn?NAVY:Color.WHITE);off.setTextColor(soundOn?Color.WHITE:NAVY);r.addView(on,weighted(1,44,4));r.addView(off,weighted(1,44,4));on.setOnClickListener(v->{soundOn=true;prefs.edit().putBoolean("sound",true).apply();play(R.raw.beep);appSettings();});off.setOnClickListener(v->{soundOn=false;prefs.edit().putBoolean("sound",false).apply();appSettings();});section("Question History");Button reset=button("RESET PLAYED QUESTIONS",RED);reset.setOnClickListener(v->confirmResetQuestions());content.addView(reset,new LinearLayout.LayoutParams(-1,dp(44)));section("App Information");TextView info=text(categories.size()+" unique categories (250 Easy • 250 Hard)\nNo repeats until a difficulty pool is completed\n5/10-second timer • Version 1.4",14,Color.WHITE);info.setBackground(bg(PANEL,15));content.addView(info,new LinearLayout.LayoutParams(-1,0,1));Button back=button("BACK",GOLD);back.setTextColor(NAVY);back.setOnClickListener(v->home());bottom(back,46);}
 EditText edit(String v){EditText e=new EditText(this);e.setText(v);e.setTextColor(Color.WHITE);e.setHintTextColor(PALE);e.setTextSize(17);e.setSingleLine(true);e.setSelectAllOnFocus(true);e.setPadding(dp(14),0,dp(14),0);e.setBackground(bg(PANEL,13));return e;}ToggleButton toggle(String s){ToggleButton t=new ToggleButton(this);t.setTag(s);t.setText(s);t.setTextOn(s);t.setTextOff(s);t.setTextColor(Color.WHITE);t.setTextSize(13);t.setAllCaps(false);t.setMinHeight(0);t.setMinimumHeight(0);t.setPadding(dp(5),0,dp(5),0);t.setGravity(Gravity.CENTER);t.setBackground(bg(PANEL,13));return t;}void styleToggle(ToggleButton t,boolean on){String s=String.valueOf(t.getTag());t.setText(on?"✓  "+s:s);t.setTextColor(on?NAVY:Color.WHITE);t.setTypeface(null,on?Typeface.BOLD:Typeface.NORMAL);t.setBackground(bg(on?GOLD:PANEL,13));}void single(LinearLayout g,ToggleButton chosen){for(int i=0;i<g.getChildCount();i++){View v=g.getChildAt(i);if(v!=chosen&&v instanceof ToggleButton)((ToggleButton)v).setChecked(false);}}
 void settings(){screen="settings";base();title("Game Settings");LinearLayout columns=new LinearLayout(this);columns.setOrientation(LinearLayout.HORIZONTAL);content.addView(columns,new LinearLayout.LayoutParams(-1,0,1));LinearLayout left=new LinearLayout(this),right=new LinearLayout(this);left.setOrientation(LinearLayout.VERTICAL);right.setOrientation(LinearLayout.VERTICAL);LinearLayout.LayoutParams col=new LinearLayout.LayoutParams(0,-1,1);col.setMargins(dp(4),0,dp(4),0);columns.addView(left,col);columns.addView(right,col);settingsLabel(left,"Difficulty");LinearLayout dif=settingsRow(left);for(String x:new String[]{"Easy","Hard"}){ToggleButton t=toggle(x);boolean sel=difficulty.equals(x.toUpperCase(Locale.ROOT));t.setChecked(sel);styleToggle(t,sel);dif.addView(t,weighted(1,43,3));t.setOnCheckedChangeListener((b,c)->{styleToggle(t,c);if(c){difficulty=x.toUpperCase(Locale.ROOT);single(dif,t);}});}settingsLabel(left,"Turn Timer");LinearLayout times=settingsRow(left);for(int n:new int[]{5,10}){ToggleButton t=toggle(n+" seconds");boolean sel=turnSeconds==n;t.setChecked(sel);styleToggle(t,sel);times.addView(t,weighted(1,43,3));t.setOnCheckedChangeListener((b,c)->{styleToggle(t,c);if(c){turnSeconds=n;single(times,t);}});}settingsLabel(right,"Winning Score");LinearLayout scores=settingsRow(right);for(int n:new int[]{3,5,7,10}){ToggleButton t=toggle(n+" pts");boolean sel=targetScore==n;t.setChecked(sel);styleToggle(t,sel);scores.addView(t,weighted(1,43,2));t.setOnCheckedChangeListener((b,c)->{styleToggle(t,c);if(c){targetScore=n;single(scores,t);}});}settingsLabel(right,"First Player");LinearLayout first=settingsRow(right);for(String x:new String[]{"Dan","Norlyn","Random"}){ToggleButton t=toggle(x);String value=x.equals("Dan")?"Player 1":x.equals("Norlyn")?"Player 2":"Random";boolean sel=firstChoice.equals(value);t.setChecked(sel);styleToggle(t,sel);first.addView(t,weighted(1,43,2));t.setOnCheckedChangeListener((b,c)->{styleToggle(t,c);if(c){firstChoice=value;single(first,t);}});}Button start=button("GAME START",GOLD);start.setTextColor(NAVY);start.setOnClickListener(v->startSession());bottom(start,47);Button back=button("BACK",PANEL);back.setOnClickListener(v->howTo());bottom(back,42);}
 void settingsLabel(LinearLayout parent,String s){TextView t=text(s,14,GOLD);t.setTypeface(null,Typeface.BOLD);t.setGravity(Gravity.START|Gravity.CENTER_VERTICAL);t.setPadding(dp(10),dp(2),dp(10),dp(2));LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,dp(32));p.setMargins(0,dp(2),0,dp(2));parent.addView(t,p);}LinearLayout settingsRow(LinearLayout parent){LinearLayout r=new LinearLayout(this);r.setOrientation(LinearLayout.HORIZONTAL);parent.addView(r,new LinearLayout.LayoutParams(-1,dp(43)));return r;}
 void hideKeyboard(){View v=getCurrentFocus();if(v!=null)((InputMethodManager)getSystemService(INPUT_METHOD_SERVICE)).hideSoftInputFromWindow(v.getWindowToken(),0);}void startSession(){p1Score=p2Score=0;round=1;roundStarter="Player 2".equals(firstChoice)?p2:("Random".equals(firstChoice)?(rng.nextBoolean()?p1:p2):p1);pickCategory();}
 void pickCategory(){ArrayList<GameData.Category> pool=new ArrayList<>();for(GameData.Category c:categories)if(c.difficulty.equals(difficulty)&&!prefs.getBoolean(key(c),false))pool.add(c);if(pool.isEmpty()){resetUsed(difficulty);for(GameData.Category c:categories)if(c.difficulty.equals(difficulty))pool.add(c);}GameData.Category c=pool.get(rng.nextInt(pool.size()));currentCategory=c.text;prefs.edit().putBoolean(key(c),true).apply();questionPage();}String key(GameData.Category c){return"used|"+c.difficulty+"|"+c.text.toLowerCase(Locale.ROOT);}void resetUsed(String d){SharedPreferences.Editor e=prefs.edit();for(String k:prefs.getAll().keySet())if(k.startsWith("used|"+d+"|"))e.remove(k);e.apply();}void resetAllUsed(){resetUsed("EASY");resetUsed("HARD");}void confirmResetQuestions(){showStyledDialog("SETTINGS","Reset question history?","Puwedeng lumabas ulit ang lahat ng 500 questions. Hindi maaapektuhan ang sound setting.",new String[]{"RESET QUESTIONS","CANCEL"},new int[]{RED,NAVY},new int[]{Color.WHITE,PALE},new Runnable[]{()->{resetAllUsed();Toast.makeText(this,"Question history reset.",Toast.LENGTH_SHORT).show();appSettings();},()->{}});}
 void scoreBar(){LinearLayout r=row();TextView a=text(p1.toUpperCase(Locale.ROOT)+"  "+p1Score,17,Color.WHITE),b=text(p2.toUpperCase(Locale.ROOT)+"  "+p2Score,17,Color.WHITE);a.setTypeface(null,Typeface.BOLD);b.setTypeface(null,Typeface.BOLD);a.setBackground(bg(PANEL,12));b.setBackground(bg(PANEL,12));r.addView(a,weighted(1,47,4));r.addView(b,weighted(1,47,4));}
 void questionPage(){screen="question";base();lastAnsweringPlayer=null;scoreBar();content.addView(text("ROUND "+round+" • "+difficulty+" • "+turnSeconds+" SEC",14,GOLD));TextView q=text(currentCategory,30,Color.WHITE);q.setTypeface(null,Typeface.BOLD);q.setBackground(bg(PANEL,19));LinearLayout.LayoutParams qp=new LinearLayout.LayoutParams(-1,0,1);qp.setMargins(0,dp(8),0,dp(8));content.addView(q,qp);TextView who=text(roundStarter+" ang unang sasagot",19,GOLD);who.setTypeface(null,Typeface.BOLD);content.addView(who,new LinearLayout.LayoutParams(-1,dp(42)));Button start=button("START ROUND",GOLD);start.setTextColor(NAVY);start.setOnClickListener(v->{activePlayer=roundStarter;remainingMs=turnMs();roundOver=false;arena(false);});bottom(start,48);Button end=button("END GAME",PANEL);end.setOnClickListener(v->confirmHome());bottom(end,42);}
 void arena(boolean beginNow){screen="arena";base();scoreBar();LinearLayout header=row();TextView cat=text(currentCategory,20,Color.WHITE);cat.setTypeface(null,Typeface.BOLD);cat.setBackground(bg(PANEL,12));Button swap=button("⇄",PURPLE);header.addView(cat,new LinearLayout.LayoutParams(0,dp(50),1));LinearLayout.LayoutParams sp=new LinearLayout.LayoutParams(dp(72),dp(50));sp.setMargins(dp(8),0,0,0);header.addView(swap,sp);swap.setOnClickListener(v->{if(!timerRunning){leftIsP1=!leftIsP1;arena(false);}});LinearLayout field=new LinearLayout(this);field.setOrientation(LinearLayout.HORIZONTAL);field.setGravity(Gravity.CENTER);content.addView(field,new LinearLayout.LayoutParams(-1,0,1));String left=leftIsP1?p1:p2,right=leftIsP1?p2:p1;Button lb=playerButton(left),rb=playerButton(right);LinearLayout center=new LinearLayout(this);center.setOrientation(LinearLayout.VERTICAL);center.setGravity(Gravity.CENTER);TextView timer=text(String.valueOf((remainingMs+999)/1000),54,Color.WHITE);timer.setTag("timer");timer.setTypeface(null,Typeface.BOLD);timer.setBackground(bg(PANEL,18));center.addView(timer,new LinearLayout.LayoutParams(dp(115),dp(95)));TextView turn=text(activePlayer+"'s turn",15,GOLD);center.addView(turn,new LinearLayout.LayoutParams(dp(150),dp(42)));Button challenge=button("CHALLENGE",RED);challenge.setTextSize(12);challenge.setEnabled(beginNow&&lastAnsweringPlayer!=null);challenge.setAlpha(challenge.isEnabled()?1f:.45f);challenge.setOnClickListener(v->challenge());center.addView(challenge,new LinearLayout.LayoutParams(dp(145),dp(44)));field.addView(lb,new LinearLayout.LayoutParams(0,-1,1));LinearLayout.LayoutParams cp=new LinearLayout.LayoutParams(dp(170),-1);cp.setMargins(dp(10),0,dp(10),0);field.addView(center,cp);field.addView(rb,new LinearLayout.LayoutParams(0,-1,1));configurePlayerButtons(lb,rb,left,beginNow);Button pause=button("PAUSE / END GAME",MUTED);pause.setOnClickListener(v->pause());bottom(pause,45);}
 Button playerButton(String name){Button b=button(name,PANEL);b.setTextSize(24);b.setTag(name);LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-1);p.setMargins(dp(4),dp(10),dp(4),dp(8));b.setLayoutParams(p);return b;}
 void configurePlayerButtons(Button lb,Button rb,String left,boolean beginNow){Button active=left.equals(activePlayer)?lb:rb,other=active==lb?rb:lb;if(beginNow){timerRunning=true;active.setText(activePlayer.toUpperCase(Locale.ROOT)+"\nSAGOT NA!");active.setEnabled(true);active.setBackground(bg(TEAL,20));other.setText(String.valueOf(other.getTag()).toUpperCase(Locale.ROOT)+"\nMAGHINTAY");other.setEnabled(false);other.setBackground(bg(MUTED,20));active.setOnClickListener(v->completeAnswer());startCountdown();}else{timerRunning=false;active.setText(activePlayer.toUpperCase(Locale.ROOT)+"\nUNANG SASAGOT");active.setEnabled(false);active.setBackground(bg(MUTED,20));other.setText(String.valueOf(other.getTag()).toUpperCase(Locale.ROOT)+"\nSTART");other.setEnabled(true);other.setBackground(bg(GOLD,20));other.setTextColor(NAVY);other.setOnClickListener(v->{play(R.raw.beep);remainingMs=turnMs();arena(true);});}}
 void completeAnswer(){if(!timerRunning||roundOver)return;cancelTimer();timerRunning=false;play(R.raw.beep);lastAnsweringPlayer=activePlayer;activePlayer=other(activePlayer);remainingMs=turnMs();new Handler().postDelayed(()->{if(!roundOver)arena(true);},250);}void startCountdown(){cancelTimer();countdown=new CountDownTimer(remainingMs,100){long last=-1;public void onTick(long ms){remainingMs=ms;long sec=(ms+999)/1000;TextView t=root.findViewWithTag("timer");if(t!=null){t.setText(String.valueOf(sec));t.setTextColor(sec<=2?RED:Color.WHITE);}if(sec!=last&&sec>=1&&sec<=turnSeconds){last=sec;play(R.raw.tick);}}public void onFinish(){remainingMs=0;timerRunning=false;if(!roundOver){play(R.raw.buzzer);awardPoint(other(activePlayer),activePlayer+" ran out of time");}}}.start();}
 void challenge(){if(!timerRunning||lastAnsweringPlayer==null)return;cancelTimer();timerRunning=false;final String challenged=lastAnsweringPlayer;final String nextPlayer=activePlayer;final long nextRemaining=remainingMs;showStyledDialog("CHALLENGE",challenged+"'s answer","Mali, naulit, o hindi pasok sa category ang sagot?",new String[]{"INVALID / REPEATED","VALID ANSWER","CANCEL"},new int[]{RED,GOLD,NAVY},new int[]{Color.WHITE,NAVY,PALE},new Runnable[]{()->{lastAnsweringPlayer=null;play(R.raw.buzzer);awardPoint(other(challenged),"Invalid answer by "+challenged);},()->{activePlayer=nextPlayer;lastAnsweringPlayer=null;remainingMs=turnMs();arena(true);},()->{activePlayer=nextPlayer;lastAnsweringPlayer=challenged;remainingMs=nextRemaining;arena(true);}});}
 Button dialogButton(String label,int fill,int textColor){Button b=button(label,fill);b.setTextColor(textColor);b.setTextSize(14);GradientDrawable shape=bg(fill,13);shape.setStroke(dp(1),GOLD);b.setBackground(shape);return b;}
 void showStyledDialog(String eyebrow,String heading,String message,String[] labels,int[] fills,int[] textColors,Runnable[] actions){final Dialog dialog=new Dialog(this);dialog.setCancelable(false);LinearLayout card=new LinearLayout(this);card.setOrientation(LinearLayout.VERTICAL);card.setPadding(dp(24),dp(20),dp(24),dp(20));GradientDrawable cardBg=bg(PANEL,20);cardBg.setStroke(dp(2),GOLD);card.setBackground(cardBg);TextView tag=text(eyebrow,13,GOLD);tag.setTypeface(null,Typeface.BOLD);tag.setLetterSpacing(.12f);card.addView(tag,new LinearLayout.LayoutParams(-1,dp(34)));TextView head=text(heading,24,Color.WHITE);head.setTypeface(null,Typeface.BOLD);card.addView(head,new LinearLayout.LayoutParams(-1,dp(48)));TextView body=text(message,16,PALE);body.setLineSpacing(0,1.12f);LinearLayout.LayoutParams mp=new LinearLayout.LayoutParams(-1,-2);mp.setMargins(0,0,0,dp(14));card.addView(body,mp);for(int i=0;i<labels.length;i++){Button action=dialogButton(labels[i],fills[i],textColors[i]);LinearLayout.LayoutParams ap=new LinearLayout.LayoutParams(-1,dp(i==labels.length-1&&labels.length>1?45:50));if(i>0)ap.setMargins(0,dp(9),0,0);card.addView(action,ap);final int index=i;action.setOnClickListener(v->{dialog.dismiss();actions[index].run();});}dialog.setContentView(card);dialog.setOnShowListener(d->{Window win=dialog.getWindow();if(win!=null){win.setBackgroundDrawable(new ColorDrawable(Color.TRANSPARENT));win.setDimAmount(.72f);win.addFlags(WindowManager.LayoutParams.FLAG_DIM_BEHIND);win.setLayout(Math.min(dp(460),getResources().getDisplayMetrics().widthPixels-dp(50)),WindowManager.LayoutParams.WRAP_CONTENT);}});dialog.show();}
 void awardPoint(String winner,String reason){if(roundOver)return;roundOver=true;cancelTimer();int old=score(winner);setScore(winner,old+1);result(winner,reason);}int score(String p){return p.equals(p1)?p1Score:p2Score;}void setScore(String p,int n){if(p.equals(p1))p1Score=n;else p2Score=n;}String other(String p){return p.equals(p1)?p2:p1;}
 void result(String winner,String reason){screen="result";base();scoreBar();content.addView(new Space(this),new LinearLayout.LayoutParams(1,0,1));TextView x=text("✕",58,RED);x.setTypeface(null,Typeface.BOLD);content.addView(x);TextView w=text(winner+" gets the point!",29,GOLD);w.setTypeface(null,Typeface.BOLD);content.addView(w);content.addView(text(reason,17,Color.WHITE));content.addView(new Space(this),new LinearLayout.LayoutParams(1,0,1));boolean won=score(winner)>=targetScore;Button next=button(won?"SEE FINAL RESULT":"NEXT ROUND",GOLD);next.setTextColor(NAVY);next.setOnClickListener(v->{if(won)victory(winner);else{round++;roundStarter=other(roundStarter);pickCategory();}});bottom(next,48);Button undo=button("UNDO POINT",PANEL);undo.setOnClickListener(v->{setScore(winner,Math.max(0,score(winner)-1));roundOver=false;remainingMs=turnMs();questionPage();});bottom(undo,42);}
 void victory(String winner){screen="victory";base();content.addView(new Space(this),new LinearLayout.LayoutParams(1,0,1));content.addView(text("🏆",65,GOLD));TextView w=text(winner.toUpperCase(Locale.ROOT)+" WINS!",34,GOLD);w.setTypeface(null,Typeface.BOLD);content.addView(w);content.addView(text(p1+"  "+p1Score+"  —  "+p2Score+"  "+p2,24,Color.WHITE));content.addView(new Space(this),new LinearLayout.LayoutParams(1,0,1));Button again=button("PLAY AGAIN",GOLD);again.setTextColor(NAVY);again.setOnClickListener(v->settings());bottom(again,55);Button h=button("HOME",PANEL);h.setOnClickListener(v->home());bottom(h,48);}
 void pause(){if(timerRunning)cancelTimer();timerRunning=false;showStyledDialog("GAME MENU","Game Paused",activePlayer+" has "+Math.max(1,(remainingMs+999)/1000)+" seconds remaining.",new String[]{"RESUME","CANCEL ROUND","END GAME"},new int[]{GOLD,NAVY,RED},new int[]{NAVY,PALE,Color.WHITE},new Runnable[]{()->arena(true),()->questionPage(),()->home()});}void confirmHome(){cancelTimer();showStyledDialog("GAME MENU","End this game?","Mawawala ang scores at round progress.",new String[]{"END GAME","CANCEL"},new int[]{RED,NAVY},new int[]{Color.WHITE,PALE},new Runnable[]{()->home(),()->{}});}void play(int raw){if(!soundOn)return;try{MediaPlayer p=MediaPlayer.create(this,raw);if(p!=null){p.setOnCompletionListener(MediaPlayer::release);p.start();}}catch(Exception ignored){}}void cancelTimer(){if(countdown!=null){countdown.cancel();countdown=null;}}
 @Override public void onWindowFocusChanged(boolean hasFocus){super.onWindowFocusChanged(hasFocus);if(hasFocus)hideSystemUI();}@Override public void onBackPressed(){if("home".equals(screen))super.onBackPressed();else if("how".equals(screen)||"appSettings".equals(screen))home();else if("settings".equals(screen))howTo();else confirmHome();}@Override protected void onDestroy(){cancelTimer();super.onDestroy();}
 static class LogoView extends View{Paint p=new Paint(3);LogoView(Context c){super(c);}protected void onDraw(Canvas c){float w=getWidth(),h=getHeight(),cx=w/2;p.setTextAlign(Paint.Align.CENTER);p.setTypeface(Typeface.create(Typeface.DEFAULT,Typeface.BOLD));p.setColor(PANEL);c.drawRoundRect(cx-w*.23f,h*.02f,cx+w*.23f,h*.46f,w*.05f,w*.05f,p);p.setColor(GOLD);p.setTextSize(h*.28f);c.drawText("⚡",cx,h*.34f,p);p.setColor(Color.WHITE);p.setTextSize(h*.17f);c.drawText("CATEGORY",cx,h*.70f,p);p.setColor(GOLD);p.setTextSize(h*.23f);c.drawText("CLASH",cx,h*.94f,p);}}
}
